# Batch 12 — more saint-poet bhajans (public-domain texts; proofreading against printed editions pending). Bhavarth is OmKiran Bhakti's own writing.
BH12 = [
 dict(n=2,slug='main-to-sanware-ke-rang-rachi.html',art='krishna',author='मीराबाई',first='मैं तो साँवरे के रंग राची',text='मैं तो साँवरे के रंग राची।\nसाजि सिंगार बाँधि पग घुँघरू, लोक-लाज तजि नाची॥\nगई कुमति, लई साधु की संगति, भगत रूप भई साँची।\nगाय गाय हरि के गुण निसदिन, काल ब्याल सूँ बाँची॥\nउण बिन सब जग खारो लागत, और बात सब काँची।\nमीरा श्री गिरधरन लाल सूँ, भगति रसीली जाँची॥',bh='मीरा कहती हैं कि वे साँवरे के रंग में रँग गई हैं। शृंगार करके, पैरों में घुँघरू बाँधकर लोक-लाज छोड़कर नाचीं; कुबुद्धि छूटी और साधुओं की संगति से सच्ची भक्त बन गईं। दिन-रात हरि के गुण गाकर वे काल रूपी साँप से बच गईं — प्रभु के बिना सारा संसार उन्हें खारा लगता है।'),
 dict(n=4,slug='pag-ghungroo-bandh-meera-nachi-re.html',art='krishna',author='मीराबाई',first='पग घुँघरू बाँधि मीरां नाची',text='पग घुँघरू बाँधि मीरां नाची।\nमैं तो मेरे नारायण सूँ, आपहि हो गई साची॥\nलोग कहै, मीरां भइ बावरी; न्यात कहै कुल-नासी।\nविस का प्याला राणा भेज्या, पीवत मीरां हाँसी॥\nमीरां के प्रभु गिरधर नागर, सहज मिले अविनासी॥',bh='मीरा पैरों में घुँघरू बाँधकर नाचीं और अपने नारायण की सच्ची हो गईं। लोग उन्हें बावरी कहते हैं, बिरादरी कुल का नाश करने वाली कहती है; राणा ने विष का प्याला भेजा तो मीरा हँसते हुए पी गईं। मीरा कहती हैं — उन्हें अविनाशी गिरधर नागर सहज ही मिल गए।'),
 dict(n=7,slug='shyam-mhane-chakar-rakho-ji.html',art='krishna',author='मीराबाई',first='स्याम म्हाने चाकर राखो जी',text='स्याम म्हाने चाकर राखो जी, गिरधारी लाला म्हाँने चाकर राखो जी।\nचाकर रहस्यूँ बाग लगास्यूँ, नित उठ दरसण पास्यूँ।\nबिन्दरावन री कुंज गली में, गोविन्द लीला गास्यूँ॥\nचाकरी में दरसण पास्यूँ, सुमरण पास्यूँ खरची।\nभाव भगती जागीरी पास्यूँ, तीनूँ बाताँ सरसी॥\nमोर मुगट पीताम्बर सौहे, गल वैजन्ती माला।\nबिन्दरावन में धेनु चरावे, मोहन मुरली वाला॥\nऊँचा ऊँचा महल बणावँ, बिच बिच राखूँ बारी।\nसाँवरिया रा दरसण पास्यूँ, पहर कुसुम्बी साड़ी॥\nआधी रात प्रभु दरसण दीज्यो, जमनाजी रे तीरा।\nमीराँ रा प्रभु गिरधर नागर, हिवड़ो घणो अधीरा॥',bh='मीरा प्रार्थना करती हैं — हे श्याम, मुझे अपनी नौकरानी (चाकर) रख लो। नौकरी में मुझे रोज़ आपके दर्शन मिलेंगे, वेतन में आपका स्मरण और जागीर में भाव-भक्ति — ये तीनों ही मेरे लिए सबसे बड़ी कमाई हैं। मैं वृंदावन की गलियों में आपकी लीला गाऊँगी।'),
 dict(n=8,slug='mai-ri-main-to-liyo-govindo-mol.html',art='krishna',author='मीराबाई',first='माई री मैं तो लियो गोविंदो मोल',text='माई री मैं तो लियो गोविंदो मोल।\nकोई कहै छानै, कोई कहै छुपकै, लियो री बजंता ढोल॥\nकोई कहै मुँहघो, कोई कहै सुहँगो, लियो री तराजू तोल।\nकोई कहै कारो, कोई कहै गोरो, लियो री अमोलक मोल॥\nयाही कूँ सब जाणत है, लियो री आँखी खोल।\nमीरा कूँ प्रभु दरसण दीज्यो, पूरब जनम को कोल॥',bh='मीरा कहती हैं — सखी, मैंने तो गोविंद को मोल ले लिया है। कोई कहता है छिपकर लिया, पर मैंने ढोल बजाकर, तराजू में तौलकर, आँखें खोलकर लिया है। कोई महँगा कहे या सस्ता, काला कहे या गोरा — मेरे लिए वे अनमोल हैं।'),
 dict(n=9,slug='man-re-parasi-hari-ke-charan.html',art='vishnu',author='मीराबाई',first='मन रे परसि हरि के चरण',text='मन रे परसि हरि के चरण।\nसुभग सीतल कमल कोमल, त्रिविध ज्वाला हरण॥\nजो चरण प्रह्लाद परसे, इंद्र पदवी धरण।\nजिन चरण ध्रुव अटल कीन्हें, राखि अपनी सरण॥\nजिन चरण ब्रह्मांड भेट्यो, नखसिखाँ सिरी धरण।\nजिन चरण प्रभु परसि लीन्हें, तरी गोतम घरण॥\nजिन चरण कालीनाग नाथ्यो, गोप लीला करण।\nजिन चरण गोबरधन धार्यो, गर्व मघवा हरण॥\nदासि मीरा लाल गिरधर, अगम तारण तरण॥',bh='मीरा अपने मन से कहती हैं — हरि के चरणों को छू ले। ये वही चरण हैं जिन्होंने प्रह्लाद और ध्रुव को अटल पद दिया, अहिल्या को तारा, कालिया नाग को नाथा और गोवर्धन उठाकर इंद्र का घमंड तोड़ा। ये चरण संसार के तीनों तापों को हरने वाले हैं।'),
 dict(n=12,slug='prabhu-more-avgun-chit-na-dharo.html',art='vishnu',author='सूरदास',first='प्रभु मोरे अवगुन चित न धरो',text='प्रभु मोरे अवगुन चित न धरो।\nसमदरसी है नाम तिहारो, चाहे तो पार करो॥\nइक लोहा पूजा में राखत, इक घर बधिक परो।\nसो दुविधा पारस नहिं जानत, कंचन करत खरो॥\nइक नदिया इक नार कहावत, मैलो नीर भरो।\nजब मिलि गए तब एक बरन ह्वै, गंगा नाम परो॥\nतन माया ज्यौं ब्रह्म कहावत, सूर सु मिलि बिगरो।\nकै इनको निरधार कीजिये, कै प्रन जात टरो॥',bh='सूरदास प्रार्थना करते हैं — प्रभु, मेरे अवगुणों पर ध्यान मत दीजिए; आपका नाम ही समदर्शी है। जैसे पारस लोहे को सोना बना देता है, चाहे वह पूजा का हो या कसाई का, और जैसे हर नदी गंगा में मिलकर गंगा हो जाती है, वैसे ही मुझे भी अपना लीजिए।'),
 dict(n=13,slug='maiya-mohi-dau-bahut-khijhayo.html',art='krishna',author='सूरदास',first='मैया मोहिं दाऊ बहुत खिझायो',text='मैया मोहिं दाऊ बहुत खिझायो।\nमोसों कहत मोल को लीन्हों, तू जसुमति कब जायो?\nकहा करौं इहि रिस के मारें, खेलन हौं नहिं जात।\nपुनि पुनि कहत कौन है माता, को है तेरो तात?\nगोरे नंद जसोदा गोरी, तू कत स्यामल गात।\nचुटकी दै दै ग्वाल नचावत, हँसत सबै मुसुकात॥\nतू मोहीं को मारन सीखी, दाउहिं कबहुँ न खीझै।\nमोहन मुख रिस की ये बातैं, जसुमति सुनि सुनि रीझै॥\nसुनहु कान्ह बलभद्र चबाई, जनमत ही को धूत।\nसूर स्याम मोहिं गोधन की सौं, हौं माता तू पूत॥',bh='बाल कृष्ण माँ यशोदा से शिकायत करते हैं कि दाऊ (बलराम) उन्हें चिढ़ाते हैं — कहते हैं तुझे मोल लिया है, नंद-यशोदा तो गोरे हैं, तू साँवला कैसे? यशोदा कान्हा की रूठी बातें सुनकर निहाल होती हैं और कहती हैं कि बलराम तो जन्म से ही चुगलखोर है, गोधन की सौगंध, मैं ही तेरी माँ हूँ।'),
 dict(n=14,slug='maiya-kabahi-badhegi-choti.html',art='krishna',author='सूरदास',first='मैया',text='मैया, कबहिं बढ़ैगी चोटी?\nकिती बार मोहिं दूध पियत भइ, यह अजहूँ है छोटी॥\nतू जो कहति बल की बेनी ज्यौं, ह्वै है लाँबी मोटी।\nकाढ़त गुहत न्हवावत जैहै, नागिनि सी भुइँ लोटी॥\nकाँचौ दूध पियावति पचि पचि, देति न माखन रोटी।\nसूरज चिरजीवौ दोउ भैया, हरि हलधर की जोटी॥',bh='बाल कृष्ण माँ से पूछते हैं — मैया, मेरी चोटी कब बढ़ेगी? तूने कहा था दूध पीने से बलराम जैसी लंबी-मोटी चोटी हो जाएगी, पर कितनी बार दूध पी लिया, चोटी तो अब भी छोटी है। सूरदास इस बाल-लीला में वात्सल्य रस का सुंदर चित्र खींचते हैं।'),
 dict(n=15,slug='jasoda-hari-palne-jhulave.html',art='krishna',author='सूरदास',first='जसोदा हरि पालनैं झुलावै',text='जसोदा हरि पालनैं झुलावै।\nहलरावै, दुलराइ मल्हावै, जोइ-सोइ कछु गावै॥\nमेरे लाल कौं आउ निंदरिया, काहैं न आनि सुवावै।\nतू काहैं नहिं बेगहिं आवै, तोकौं कान्ह बुलावै॥\nकबहुँ पलक हरि मूँदि लेत हैं, कबहुँ अधर फरकावै।\nसोवत जानि मौन ह्वै कै रहि, करि करि सैन बतावै॥\nइहिं अंतर अकुलाइ उठे हरि, जसुमति मधुरैं गावै।\nजो सुख सूर अमर-मुनि दुरलभ, सो नँद-भामिनि पावै॥',bh='यशोदा जी कान्हा को पालने में झुला रही हैं, दुलार रही हैं और लोरी गा रही हैं — ‘निंदिया, तू जल्दी आकर मेरे लाल को सुला दे।’ कान्हा कभी पलकें मूँद लेते हैं, कभी होंठ फड़काते हैं। सूरदास कहते हैं कि जो सुख देवताओं और मुनियों को भी दुर्लभ है, वह नंद की पत्नी यशोदा को मिल रहा है।'),
 dict(n=16,slug='udho-man-na-bhaye-das-bees.html',art='krishna',author='सूरदास',first='ऊधौ',text='ऊधौ, मन न भए दस बीस।\nएक हुतौ सो गयौ स्याम सँग, को अवराधै ईस॥\nइंद्री सिथिल भईं केसव बिनु, ज्यौं देही बिनु सीस।\nआसा लागि रहत तन स्वासा, जीवहिं कोटि बरीस॥\nतुम तौ सखा स्याम सुंदर के, सकल जोग के ईस।\nसूर हमारैं नंदनंदन बिनु, और नहीं जगदीस॥',bh='भ्रमरगीत का यह पद गोपियों का उत्तर है। उद्धव ज्ञान और योग का संदेश लेकर आए हैं, तो गोपियाँ कहती हैं — उद्धव, हमारे दस-बीस मन नहीं हैं; एक ही मन था, वह श्याम के साथ चला गया। अब योग की आराधना किस मन से करें?'),
 dict(n=17,slug='nisidin-barsat-nain-hamare.html',art='krishna',author='सूरदास',first='निसिदिन बरसत नैन हमारे',text='निसिदिन बरसत नैन हमारे।\nसदा रहत पावस ऋतु हम पर, जब तें स्याम सिधारे॥\nअंजन थिर न रहत अँखियन में, कर कपोल भए कारे।\nकंचुकि-पट सूखत नहिं कबहूँ, उर बिच बहत पनारे॥\nआँसू सलिल भए पग थाके, बहे जात सित तारे।\nसूरदास अब डूबत है ब्रज, काहे न लेत उबारे॥',bh='श्रीकृष्ण के मथुरा जाने के बाद गोपियों का विरह — हमारी आँखें दिन-रात बरसती रहती हैं, जब से श्याम गए हैं, हम पर हमेशा बरसात का मौसम रहता है। सूरदास कहते हैं कि ब्रज आँसुओं में डूब रहा है, प्रभु आकर उबारते क्यों नहीं?'),
 dict(n=18,slug='charan-kamal-bandau-hari-rai.html',art='vishnu',author='सूरदास',first='चरन कमल बंदौं हरि राई',text='चरन कमल बंदौं हरि राई।\nजाकी कृपा पंगु गिरि लंघै, अंधे कौं सब कछु दरसाई॥\nबहिरौ सुनै, मूक पुनि बोलै, रंक चलै सिर छत्र धराई।\nसूरदास स्वामी करुनामय, बार-बार बंदौं तिहिं पाई॥',bh='सूरसागर का मंगलाचरण — मैं हरि के चरण कमलों की वंदना करता हूँ, जिनकी कृपा से लंगड़ा पहाड़ लाँघ जाता है, अंधे को सब दिखने लगता है, बहरा सुनने लगता है, गूँगा बोलने लगता है और गरीब राजा बन जाता है।'),
 dict(n=19,slug='mo-sam-kaun-kutil-khal-kami.html',art='vishnu',author='सूरदास',first='मो सम कौन कुटिल खल कामी',text='मो सम कौन कुटिल खल कामी।\nजेहिं तनु दियौ ताहिं बिसरायौ, ऐसौ नोनहरामी॥\nभरि भरि उदर बिषय कौं धावौं, जैसे सूकर ग्रामी।\nहरिजन छाँड़ि हरी-बिमुखन की, निसदिन करत गुलामी॥\nपापी कौन बड़ो है मोतें, सब पतितन में नामी।\nसूर पतित कौं ठौर कहाँ है, सुनिए श्रीपति स्वामी॥',bh='सूरदास विनय भाव में कहते हैं — मेरे जैसा कुटिल, दुष्ट और कामी कौन है? जिस प्रभु ने यह शरीर दिया, उसी को भूल गया। सूरदास अपने दोष मानकर प्रभु की शरण माँगते हैं — यह पद आत्म-निवेदन की भक्ति का उदाहरण है।'),
 dict(n=21,slug='abigat-gati-kachhu-kahat-na-aave.html',art='vishnu',author='सूरदास',first='अबिगत-गति कछु कहत न आवै',text='अबिगत-गति कछु कहत न आवै।\nज्यों गूँगे मीठे फल को रस, अंतरगत ही भावै॥\nपरम स्वाद सबही सु निरंतर, अमित तोष उपजावै।\nमन बानी कों अगम अगोचर, सो जानै जो पावै॥\nरूप रेख गुन जाति जुगति बिनु, निरालंब कित धावै।\nसब बिधि अगम बिचारहिं तातें, सूर सगुन पद गावै॥',bh='सूरदास कहते हैं — निर्गुण (अव्यक्त) ब्रह्म की गति कहने में नहीं आती। जैसे गूँगा मीठा फल खाकर उसका स्वाद मन में ही समझता है, बता नहीं सकता। जिसका कोई रूप, रेखा, गुण नहीं, उस तक मन कैसे पहुँचे — इसलिए सूर सगुण (श्रीकृष्ण) के पद गाते हैं।'),
 dict(n=23,slug='jaun-kahan-taji-charan-tumhare.html',art='ram',author='तुलसीदास',first='जाऊँ कहाँ तजि चरन तुम्हारे',text='जाऊँ कहाँ तजि चरन तुम्हारे।\nकाको नाम पतित-पावन जग, केहि अति दीन पियारे॥\nकौने देव बराइ बिरद-हित, हठि हठि अधम उधारे।\nखग, मृग, ब्याध, पषान, बिटप जड़, जवन कवन सुर तारे॥\nदेव, दनुज, मुनि, नाग, मनुज सब, माया-बिबस बिचारे।\nतिनके हाथ दासतुलसी प्रभु, कहा अपनपौ हारे॥',bh='विनय पत्रिका का पद — तुलसीदास कहते हैं, प्रभु, आपके चरण छोड़कर कहाँ जाऊँ? संसार में किसका नाम पतित-पावन है, किसे दीन इतने प्यारे हैं? पक्षी, पशु, शिकारी, पत्थर और पेड़ तक को आपने तारा। बाकी सब देवता भी माया के वश में हैं, इसलिए तुलसी ने आपके ही हाथों खुद को सौंप दिया है।'),
 dict(n=24,slug='ab-lau-nasani-ab-na-nasaihon.html',art='ram',author='तुलसीदास',first='अब लौं नसानी',text='अब लौं नसानी, अब न नसैहौं।\nराम-कृपा भव-निसा सिरानी, जागे फिरि न डसैहौं॥\nपायेउँ नाम चारु चिंतामनि, उर कर तें न खसैहौं।\nस्यामरूप सुचि रुचिर कसौटी, चित कंचनहिं कसैहौं॥\nपरबस जानि हँस्यो इन इंद्रिन, निज बस ह्वै न हँसैहौं।\nमन मधुकर पन करि तुलसी, रघुपति पद-कमल बसैहौं॥',bh='तुलसीदास संकल्प लेते हैं — अब तक का जीवन व्यर्थ गया, अब नहीं जाने दूँगा। राम-कृपा से संसार की रात बीत गई और मैं जाग गया। राम-नाम रूपी चिंतामणि मिल गई है, उसे हाथ से नहीं छोड़ूँगा; मन रूपी भौंरा अब रघुपति के चरण कमलों में ही बसेगा।'),
 dict(n=25,slug='aiso-ko-udar-jag-mahi.html',art='ram',author='तुलसीदास',first='ऐसो को उदार जग माहीं',text='ऐसो को उदार जग माहीं।\nबिनु सेवा जो द्रवै दीन पर, राम सरिस कोउ नाहीं॥\nजो गति जोग बिराग जतन करि, नहिं पावत मुनि ग्यानी।\nसो गति देत गीध सबरी कहँ, प्रभु न बहुत जिय जानी॥\nजो संपति दस सीस अरप करि, रावन सिव पहँ लीन्हीं।\nसो संपदा बिभीषन कहँ अति, सकुच-सहित हरि दीन्हीं॥\nतुलसिदास सब भाँति सकल सुख, जो चाहसि मन मेरो।\nतौ भजु राम, काम सब पूरन, करैं कृपानिधि तेरो॥',bh='तुलसीदास कहते हैं — संसार में श्रीराम जैसा उदार कौन है, जो बिना सेवा के ही दीनों पर द्रवित हो जाए? जो गति योगी-मुनि बड़े जतन से भी नहीं पाते, वह उन्होंने जटायु और शबरी को दे दी। जो संपत्ति रावण ने दस सिर चढ़ाकर पाई, वह संकोच के साथ विभीषण को दे दी। इसलिए हे मन, राम को भज।'),
 dict(n=26,slug='kesav-kahi-na-jai-ka-kahiye.html',art='ram',author='तुलसीदास',first='केसव',text='केसव, कहि न जाइ का कहिये।\nदेखत तव रचना बिचित्र हरि, समुझि मनहिं मन रहिये॥\nसून्य भीति पर चित्र, रंग नहिं, तनु बिनु लिखा चितेरे।\nधोये मिटइ न मरइ भीति, दुख पाइय एहि तनु हेरे॥\nरबिकर-नीर बसै अति दारुन, मकर रूप तेहि माहीं।\nबदन-हीन सो ग्रसै चराचर, पान करन जे जाहीं॥\nकोउ कह सत्य, झूठ कह कोऊ, जुगल प्रबल कोउ मानै।\nतुलसिदास परिहरै तीन भ्रम, सो आपन पहिचानै॥',bh='तुलसीदास कहते हैं — हे केशव, आपकी विचित्र रचना (संसार) के बारे में क्या कहूँ? यह बिना दीवार और रंग के बना चित्र है, जो धोने से मिटता नहीं। कोई इसे सत्य कहता है, कोई झूठ, कोई दोनों। तुलसी कहते हैं कि जो इन तीनों भ्रमों को छोड़ दे, वही अपने असली स्वरूप को पहचानता है।'),
 dict(n=27,slug='man-pachhitaihai-avsar-beete.html',art='ram',author='तुलसीदास',first='मन पछितैहै अवसर बीते',text='मन पछितैहै अवसर बीते।\nदुरलभ देह पाइ हरिपद भजु, करम, बचन अरु ही ते॥\nसहसबाहु, दसबदन आदि नृप, बचे न काल बलीते।\nहम हम करि धन-धाम सँवारे, अंत चले उठि रीते॥\nसुत-बनितादि जानि स्वारथरत, न करु नेह सबही ते।\nअंतहु तोहिं तजैंगे पामर! तू न तजै अबही ते॥\nअब नाथहिं अनुरागु, जागु जड़, त्यागु दुरासा जी ते।\nबुझै न काम-अगिनि तुलसी कहुँ, बिषय-भोग बहु घी ते॥',bh='तुलसीदास मन को चेताते हैं — अवसर बीत जाने पर पछताएगा। दुर्लभ मानव शरीर मिला है, मन-वचन-कर्म से हरि को भज। सहस्रबाहु और रावण जैसे राजा भी काल से नहीं बचे, सब ख़ाली हाथ गए। पत्नी-पुत्र स्वार्थ के साथी हैं, अंत में वे तुझे छोड़ देंगे, तू अभी से उनका मोह छोड़। विषय-भोग से कामना की आग नहीं बुझती, जैसे घी डालने से आग नहीं बुझती।'),
 dict(n=28,slug='kabahunk-haun-yahi-rahani-rahaungo.html',art='ram',author='तुलसीदास',first='कबहुँक हौं यहि रहनि रहौंगो',text='कबहुँक हौं यहि रहनि रहौंगो।\nश्री रघुनाथ-कृपालु-कृपा तें, संत-सुभाव गहौंगो॥\nजथालाभ संतोष सदा, काहू सों कछु न चहौंगो।\nपरहित-निरत निरंतर, मन क्रम बचन नेम निबहौंगो॥\nपरुष बचन अति दुसह स्रवन सुनि, तेहि पावक न दहौंगो।\nबिगत मान, सम सीतल मन, पर-गुन, नहिं दोष कहौंगो॥\nपरिहरि देह-जनित चिंता, दुख-सुख समबुद्धि सहौंगो।\nतुलसिदास प्रभु यहि पथ रहि, अबिचल हरि-भक्ति लहौंगो॥',bh='तुलसीदास कामना करते हैं — क्या कभी मैं संतों जैसा जीवन जी पाऊँगा? जो मिले उसी में संतोष, किसी से कुछ न चाहना, सदा दूसरों का भला करना, कठोर वचन सुनकर भी न जलना, दूसरों के गुण देखना और दोष न कहना, सुख-दुख को समान भाव से सहना — इसी रास्ते पर चलकर अटल हरि-भक्ति पाऊँगा।'),
 dict(n=30,slug='moko-kahan-dhoondhe-re-bande.html',art='vishnu',author='कबीरदास',first='मोको कहाँ ढूँढे रे बंदे',text='मोको कहाँ ढूँढे रे बंदे, मैं तो तेरे पास में।\nना मैं देवल ना मैं मसजिद, ना काबे कैलास में॥\nना तो कौने क्रिया-कर्म में, नहीं योग बैराग में।\nखोजी होय तो तुरतै मिलिहौं, पल भर की तालास में॥\nकहैं कबीर सुनो भई साधो, सब स्वाँसों की स्वाँस में॥',bh='कबीर कहते हैं — हे मनुष्य, तू मुझे (ईश्वर को) कहाँ ढूँढता है? मैं न मंदिर में हूँ, न मस्जिद में, न काबा में, न कैलाश में, न किसी क्रिया-कर्म में। सच्चा खोजी हो तो मैं पल भर में मिल जाऊँ — मैं तो हर साँस की साँस में हूँ।'),
 dict(n=31,slug='jheeni-jheeni-beeni-chadariya.html',art='vishnu',author='कबीरदास',first='झीनी झीनी बीनी चदरिया',text='झीनी झीनी बीनी चदरिया।\nकाहे कै ताना काहे कै भरनी, कौन तार से बीनी चदरिया॥\nइंगला पिंगला ताना भरनी, सुखमन तार से बीनी चदरिया।\nआठ कँवल दल चरखा डोलै, पाँच तत्त गुन तीनी चदरिया॥\nसाँई को सियत मास दस लागै, ठोक ठोक कै बीनी चदरिया।\nसो चादर सुर नर मुनि ओढ़ी, ओढ़ि कै मैली कीनी चदरिया॥\nदास कबीर जतन करि ओढ़ी, ज्यों कीं त्यों धर दीनी चदरिया॥',bh='कबीर शरीर को एक बारीक बुनी चादर बताते हैं, जिसे राम-नाम के ताने-बाने से बुना गया है। सुर, नर, मुनि सबने इसे ओढ़कर मैली कर दी, पर दास कबीर ने इसे बड़े जतन से ओढ़ा और जैसी मिली थी, वैसी ही ज्यों की त्यों लौटा दी — यानी जीवन को पवित्र रखा।'),
 dict(n=32,slug='man-lago-mero-yaar-fakiri-mein.html',art='vishnu',author='कबीरदास',first='मन लागो मेरो यार फकीरी में',text='मन लागो मेरो यार फकीरी में।\nजो सुख पावो राम भजन में, सो सुख नाहिं अमीरी में॥\nभला बुरा सब का सुन लीजै, कर गुजरान गरीबी में।\nप्रेम नगर में रहनि हमारी, भलि बनि आई सबूरी में॥\nहाथ में कूँडी बगल में सोटा, चारों दिसि जागीरी में।\nआखिर यह तन खाक मिलैगा, कहाँ फिरत मगरूरी में॥\nकहत कबीर सुनो भाई साधो, साहिब मिलै सबूरी में॥',bh='कबीर कहते हैं — मेरा मन फ़कीरी में लग गया है। जो सुख राम-भजन में है, वह अमीरी में नहीं। सबकी भली-बुरी सुनकर गरीबी में गुज़ारा कर लो; प्रेम नगर में रहो और सब्र रखो। आख़िर यह शरीर मिट्टी में मिलेगा, फिर घमंड किस बात का? साहिब सब्र से ही मिलते हैं।'),
 dict(n=33,slug='rahna-nahi-des-birana-hai.html',art='vishnu',author='कबीरदास',first='रहना नहिं देस बिराना है',text='रहना नहिं देस बिराना है।\nयह संसार कागद की पुड़िया, बूँद पड़े घुल जाना है॥\nयह संसार काँट की बाड़ी, उलझ-पुलझ मरि जाना है।\nयह संसार झाड़ और झाँखर, आग लगे बरि जाना है॥\nकहत कबीर सुनो भाई साधो, सतगुरु नाम ठिकाना है॥',bh='कबीर कहते हैं — यह संसार पराया देश है, यहाँ हमेशा नहीं रहना। यह कागज़ की पुड़िया जैसा है जो पानी की बूँद पड़ते ही घुल जाए, काँटों की बाड़ी जैसा है जिसमें उलझकर मर जाना है। सतगुरु का नाम ही असली ठिकाना है।'),
 dict(n=34,slug='santo-dekho-jag-baurana.html',art='vishnu',author='कबीरदास',first='साधो',text='साधो, देखो जग बौराना।\nसाँची कहीं तो मारन धावै, झूठे जग पतियाना॥\nनेमी देखा धरमी देखा, प्रात करै असनाना।\nआतम मारि पखानहि पूजै, उनमें कछु नहिं ज्ञाना॥\nबहुतक देखा पीर औलिया, पढ़ै कितेब कुराना।\nकै मुरीद तदबीर बतावैं, उनमें उहै जो ज्ञाना॥\nआसन मारि डिंभ धरि बैठे, मन में बहुत गुमाना।\nपीपर पाथर पूजन लागे, तीरथ गर्ब भुलाना॥\nटोपी पहिरे माला पहिरे, छाप तिलक अनुमाना।\nसाखी सब्दहि गावत भूले, आतम खबरि न जाना॥\nहिन्दू कहै मोहि राम पियारा, तुर्क कहै रहिमाना।\nआपस में दोउ लरि लरि मूए, मर्म न काहू जाना॥\nघर घर मंत्र देत फिरत हैं, महिमा के अभिमाना।\nगुरु के सहित सिख्य सब बूड़े, अंत काल पछिताना॥\nकहै कबीर सुनो हो संतो, ई सब मर्म भुलाना।\nकेतिक कहीं कहा नहिं मानै, सहजै सहज समाना॥',bh='कबीर कहते हैं — संतो, देखो दुनिया पागल हो गई है। सच कहो तो लोग मारने दौड़ते हैं और झूठ पर विश्वास करते हैं। हिंदू राम को और मुसलमान रहमान को अपना बताकर आपस में लड़ते हैं, पर असली मर्म कोई नहीं जानता। दिखावे की पूजा और नियम करने वाले भी भीतर से ख़ाली हैं।'),
 dict(n=35,slug='ghunghat-ka-pat-khol-re.html',art='vishnu',author='कबीरदास',first='घूँघट का पट खोल रे',text='घूँघट का पट खोल रे, तोको पीव मिलेंगे।\nघट घट में वह साँई रमता, कटुक बचन मत बोल रे॥\nधन जोबन का गरब न कीजै, झूठा पचरँग चोल रे।\nसुन्न महल में दियना बारि ले, आसा सों मत डोल रे॥\nजोग जुगत सों रंगमहल में, पिय पायो अनमोल रे।\nकहैं कबीर आनंद भयो है, बाजत अनहद ढोल रे॥',bh='कबीर आत्मा से कहते हैं — अज्ञान का घूँघट खोल, तुझे प्रियतम (परमात्मा) मिलेंगे। वह हर घट (हृदय) में रमता है, इसलिए किसी से कड़वा मत बोल। धन-जवानी का घमंड मत कर; मन के शून्य महल में ज्ञान का दीपक जला — तब भीतर अनहद नाद बजेगा और आनंद मिलेगा।'),
 dict(n=36,slug='maya-maha-thagini-hum-jani.html',art='vishnu',author='कबीरदास',first='माया महा ठगिनी हम जानी',text='माया महा ठगिनी हम जानी।\nतिरगुन फाँस लिए कर डोलै, बोलै मधुरी बानी॥\nकेसव के कमला ह्वै बैठी, सिव के भवन भवानी।\nपंडा के मूरत ह्वै बैठी, तीरथ हू में पानी॥\nजोगी के जोगिन ह्वै बैठी, राजा के घर रानी।\nकाहू के हीरा ह्वै बैठी, काहू के कौड़ी कानी॥\nभगतन के भगतिन ह्वै बैठी, ब्रह्मा के ब्रह्मानी।\nकहै कबीर सुनो भई साधो, यह सब अकथ कहानी॥',bh='कबीर कहते हैं — हमने जान लिया कि माया सबसे बड़ी ठगनी है। वह तीन गुणों का फंदा लिए मीठा बोलती घूमती है — विष्णु के यहाँ लक्ष्मी, शिव के यहाँ भवानी, पंडे के यहाँ मूर्ति, तीर्थ में पानी, राजा के घर रानी, किसी के यहाँ हीरा तो किसी के यहाँ कानी कौड़ी बनकर बैठी है।'),
 dict(n=37,slug='bhajo-re-bhaiya-ram-govind-hari.html',art='vishnu',author='कबीरदास',first='भजो रे भैया राम गोविंद हरी',text='भजो रे भैया राम गोविंद हरी।\nजप तप साधन कछु नहिं लागत, खरचत नहिं गठरी॥\nसंतत संपत सुख के कारन, जासे भूल परी।\nकहत कबीर राम नहिं जा मुख, ता मुख धूल भरी॥',bh='कबीर कहते हैं — भाई, राम-गोविंद-हरि का भजन करो। इसमें न जप-तप लगता है, न कोई साधन, न जेब से कुछ ख़र्च होता है। लोग धन और सुख के पीछे भूल में पड़े हैं; जिस मुख में राम नहीं, उस मुख में धूल है।'),
 dict(n=39,slug='aisi-lal-tujh-binu-kaun-kare.html',art='vishnu',author='संत रैदास',first='ऐसी लाल तुझ बिनु कउनु करै',text='ऐसी लाल तुझ बिनु कउनु करै।\nगरीब निवाजु गुसईआ मेरा, माथै छत्रु धरै॥\nजाकी छोति जगत कउ लागै, ता पर तुहीं ढरै।\nनीचहु ऊच करै मेरा गोबिंदु, काहू ते न डरै॥\nनामदेव कबीरु तिलोचनु, सधना सैनु तरै।\nकहि रविदासु सुनहु रे संतहु, हरि जीउ ते सभै सरै॥',bh='संत रविदास कहते हैं — हे प्रभु, तुम्हारे बिना ऐसा कौन कर सकता है? तुम गरीबों पर कृपा करने वाले हो, जिसे दुनिया अछूत मानती है उस पर भी दया करते हो और उसके सिर पर छत्र रखते हो। तुम नीच को ऊँचा कर देते हो। नामदेव, कबीर, त्रिलोचन, सधना और सैन जैसे संत तुम्हारी कृपा से तर गए।'),
 dict(n=41,slug='manus-haun-to-wahi-raskhan.html',art='krishna',author='रसखान',first='मानुस हौं तो वही रसखानि',text='मानुस हौं तो वही रसखानि, बसौं ब्रज गोकुल गाँव के ग्वारन।\nजौ पसु हौं तो कहा बस मेरो, चरौं नित नंद की धेनु मँझारन॥\nपाहन हौं तो वही गिरि को, जो धर्यो कर छत्र पुरंदर धारन।\nजौ खग हौं तो बसेरो करौं, मिलि कालिंदी कूल कदंब की डारन॥',bh='रसखान की कामना — अगर अगले जन्म में मनुष्य बनूँ तो ब्रज के गोकुल गाँव में ग्वाला बनूँ, पशु बनूँ तो नंद की गायों में चरूँ, पत्थर बनूँ तो उसी गोवर्धन पर्वत का बनूँ जिसे श्रीकृष्ण ने छाते की तरह उठाया था, और पक्षी बनूँ तो यमुना किनारे कदंब की डालों पर बसेरा करूँ।'),
 dict(n=42,slug='ya-lakuti-aru-kamariya-par.html',art='krishna',author='रसखान',first='या लकुटी अरु कामरिया पर',text='या लकुटी अरु कामरिया पर, राज तिहूँ पुर को तजि डारौं।\nआठहुँ सिद्धि नवोनिधि के सुख, नंद की गाइ चराइ बिसारौं॥\nरसखान कबौं इन आँखिन सौं, ब्रज के बन बाग तड़ाग निहारौं।\nकोटिक ए कलधौत के धाम, करील के कुंजन ऊपर वारौं॥',bh='रसखान कहते हैं — श्रीकृष्ण की इस लाठी और कंबल पर मैं तीनों लोकों का राज छोड़ दूँ। नंद की गायें चराने के सुख पर आठों सिद्धियाँ और नौ निधियाँ भुला दूँ। ब्रज के वन, बाग़ और करील के कुंजों पर करोड़ों सोने के महल न्योछावर कर दूँ।'),
 dict(n=43,slug='ses-ganes-mahes-dines.html',art='krishna',author='रसखान',first='सेस गनेस महेस दिनेस',text='सेस गनेस महेस दिनेस, सुरेसहु जाहि निरंतर गावैं।\nजाहि अनादि अनंत अखंड, अछेद अभेद सुबेद बतावैं॥\nनारद से सुक ब्यास रटैं, पचि हारे तऊ पुनि पार न पावैं।\nताहि अहीर की छोहरियाँ, छछिया भरि छाछ पै नाच नचावैं॥',bh='रसखान कहते हैं — जिन्हें शेषनाग, गणेश, महेश, सूर्य और इंद्र निरंतर गाते हैं, जिन्हें वेद अनादि, अनंत और अखंड बताते हैं, जिनका पार नारद, शुकदेव और व्यास भी नहीं पा सके — उन्हीं श्रीकृष्ण को अहीरों की छोकरियाँ छाछ भरी कटोरी के लिए नाच नचाती हैं। यह प्रेम की महिमा है।'),
]
